        require(limit > 0);
        require(firstAmount > 0);
        require(secondAmount > 0);

        c.AdjustBetAmounts(limit);

        address me = address(this);

        uint256 balBefore = address(this).balance;
        require(balBefore >= firstAmount);
        try c.wager{value: firstAmount}() { } catch { }

        bool firstSucceeded = c.hasPlayerWagered(me);

        if (firstSucceeded) {
            require(firstAmount == c.currentBetLimit());
        }

        if (open) {
            c.OpenToThePublic();
        } else {
