        }

        bool alreadyOpen = c.hasPlayerWagered(me);
        uint256 curLimit = c.currentBetLimit();

        uint256 bn = block.number;
        if (bn == 0) { bn = 1; }
        // advance block number by making no state change; block.number is constant in test
        // so a second wager should revert if timestamp not less than block.number?

        bool reverted;
        uint256 balBefore2 = address(this).balance;
        require(balBefore2 >= secondAmount);
        try c.wager{value: secondAmount}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        bool secondSucceeded = c.hasPlayerWagered(me);

